import java.io.*;
import java.util.*;
import org.json.*;
import android.app.usage.*;
import android.content.pm.*;
String fmt(long ms) {
  long mn = (ms + 30000L) / 60000L;
  long h = mn / 60L;
  long r = mn % 60L;
  if (h > 0) return h + " gh " + (r < 10 ? "0" : "") + r + " min";
  return r + " min";
}
void add(HashMap mp, String k, long d) {
  if (k == null || d <= 0L || d > 21600000L) return;
  Long was = (Long) mp.get(k);
  mp.put(k, new Long((was == null ? 0L : was.longValue()) + d));
}
String esc(String s) {
  if (s == null) return "?";
  s = s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
  if (s.length() > 24) s = s.substring(0, 23) + "…";
  return s;
}
try {
  HashMap tot = new HashMap();
  boolean approx = false;
  try {
    Calendar c = Calendar.getInstance();
    c.set(Calendar.HOUR_OF_DAY, 0);
    c.set(Calendar.MINUTE, 0);
    c.set(Calendar.SECOND, 0);
    c.set(Calendar.MILLISECOND, 0);
    long from = c.getTimeInMillis();
    long now = System.currentTimeMillis();
    UsageStatsManager um = (UsageStatsManager) appContext.getSystemService("usagestats");
    UsageEvents ev = um.queryEvents(from, now);
    UsageEvents.Event e = new UsageEvents.Event();
    HashMap pk = new HashMap();
    String cur = null;
    String cls = null;
    long st = 0L;
    while (ev != null && ev.hasNextEvent()) {
      ev.getNextEvent(e);
      int ty = e.getEventType();
      String p = e.getPackageName();
      long ts = e.getTimeStamp();
      if (ty == 1) {
        if (cur != null && !cur.equals(p)) {
          add(pk, cur, ts - st);
          cur = null;
        }
        if (cur == null) {
          cur = p;
          st = ts;
        }
        cls = e.getClassName();
      } else if (ty == 2) {
        String k2 = e.getClassName();
        if (cur != null && cur.equals(p) && (cls == null || k2 == null || cls.equals(k2))) {
          add(pk, cur, ts - st);
          cur = null;
        }
      } else if (ty == 16 || ty == 17 || ty == 26 || ty == 27) {
        if (cur != null) {
          add(pk, cur, ts - st);
          cur = null;
        }
      }
    }
    if (cur != null) add(pk, cur, now - st);
    PackageManager pm = appContext.getPackageManager();
    Iterator it = pk.keySet().iterator();
    while (it.hasNext()) {
      String p = (String) it.next();
      String nm = p;
      try {
        nm = pm.getApplicationLabel(pm.getApplicationInfo(p, 0)).toString();
      } catch (Exception e3) {
        nm = p;
      }
      add(tot, nm, ((Long) pk.get(p)).longValue());
    }
  } catch (Throwable t1) {
    tot = new HashMap();
  }
  if (tot.size() == 0) {
    approx = true;
    try {
      File f = new File("/storage/emulated/0/MacroDroid/Claude/st.json");
      if (f.exists()) {
        BufferedReader r = new BufferedReader(new InputStreamReader(new FileInputStream(f), "UTF-8"));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = r.readLine()) != null) sb.append(line);
        r.close();
        JSONObject o = new JSONObject(sb.toString());
        JSONObject m = o.optJSONObject("m");
        if (m != null && "{dayofmonth}".equals(o.optString("d"))) {
          Iterator ks = m.keys();
          while (ks.hasNext()) {
            String k = (String) ks.next();
            add(tot, k, m.optInt(k, 0) * 60000L);
          }
        }
      }
    } catch (Throwable t2) {
      tot = new HashMap();
    }
  }
  int n = tot.size();
  if (n == 0) return "📱 Screen time: abhi data nahi";
  String[] ns = new String[n];
  long[] vs = new long[n];
  int i = 0;
  long all = 0L;
  Iterator it2 = tot.keySet().iterator();
  while (it2.hasNext()) {
    String k = (String) it2.next();
    ns[i] = k;
    vs[i] = ((Long) tot.get(k)).longValue();
    all += vs[i];
    i++;
  }
  for (int a = 0; a < n - 1; a++) {
    int b = a;
    for (int q = a + 1; q < n; q++) if (vs[q] > vs[b]) b = q;
    if (b != a) {
      long tv = vs[a];
      vs[a] = vs[b];
      vs[b] = tv;
      String tn = ns[a];
      ns[a] = ns[b];
      ns[b] = tn;
    }
  }
  StringBuilder out = new StringBuilder();
  out.append("📱 <b>Aaj ka screen time</b>");
  if (approx) out.append(" ≈");
  int top = n < 5 ? n : 5;
  long rest = 0L;
  int restN = 0;
  for (int a = 0; a < n; a++) {
    if (a < top) out.append("<br>").append(a + 1).append(". ").append(esc(ns[a])).append(" — <b>").append(fmt(vs[a])).append("</b>");
    else {
      rest += vs[a];
      restN++;
    }
  }
  if (restN > 0) out.append("<br>➕ Baqi ").append(restN).append(" apps — <b>").append(fmt(rest)).append("</b>");
  out.append("<br>⏱ <b>Kul: ").append(fmt(all)).append("</b>");
  return out.toString();
} catch (Throwable t) {
  return "📱 Screen time: ginti na ho saki";
}
